import { isNil, truncate } from 'lodash-es';
import React, { ReactNode } from 'react';
import { FormattedList, FormattedMessage, FormattedPlural } from 'react-intl';
import styled from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';
import {
  FieldType,
  FieldTypeType,
  RangedFieldTypes,
} from '@dynatrace-sdk/client-query';
import {
  ConvertibleUnit,
  convert,
  format,
  formatUnit,
} from '@dynatrace-sdk/units';

import { getTypesForRecordIndex } from './getFieldsArrayForRecordIndex.js';
import {
  ConversionCellValue,
  fallbackRenderer,
  formatDqlNumber,
} from './unit-utils.js';
import { _formatDate } from '../core/utils/create-datetime-default-formatter.js';
import { Emphasis } from '../typography/Emphasis.js';
import { Text } from '../typography/Text.js';

const MAX_PREVIEW_VALUES = 10;

const StyledComplexRecordPlaceholder: typeof Text = /* @__PURE__ */ styled(
  Text,
)({
  display: 'inline',
  color: Colors.Text.Neutral.Subdued,
});

/** Placeholder message component used when a record is too complex to display */
const ComplexQueryRecordPlaceholder = () => (
  <StyledComplexRecordPlaceholder textStyle="base-emphasized" as="p">
    <FormattedMessage
      defaultMessage="Complex record"
      id="v+sq+1W27wyL/ncS"
      description="Message to display for query records that are too complex to stringify"
    />
  </StyledComplexRecordPlaceholder>
);

/** available options for the largeTextTruncation option of the CellRendererOptions. */
export type CellRendererTextTruncationOptions = {
  maxLength: number;
  omission: string;
};

/** Formatting options for the cellRenderer function. */
export type CellRendererOptions = {
  largeTextTruncation?: CellRendererTextTruncationOptions;
};

const truncateString = (
  value: unknown,
  options: CellRendererTextTruncationOptions | undefined,
) => {
  if (typeof value !== 'string' || !options) {
    return value;
  }

  return truncate(value, {
    length: options.maxLength,
    omission: options.omission,
  });
};

/**
 * Renders a cell for a given type.
 * @param cellValue - value of the cell
 * @param fieldType - field type
 * @param unit - string unit that comes from Grail, or a formatter object
 * accepted by the SDK unit `format` utility in the case of unit overrides.
 * @param options - additional formatting options
 * @deprecated Moved to data-exploration repository.
 */
export function cellRenderer(
  cellValue: ConversionCellValue,
  fieldType: FieldType | undefined,
  unit?: Parameters<typeof formatDqlNumber>[2],
  options: CellRendererOptions = {},
): ReactNode {
  // Special case. We want to show an empty cell in the table
  // if the value and type is explicitly `undefined`
  // Without this, we would render a table full of `undefined` in some situations
  if (cellValue === undefined && fieldType === undefined) {
    return '';
  }

  // render `null` or `undefined` to the cell
  if (isNil(cellValue) || fieldType?.type === FieldTypeType.Undefined) {
    return <Emphasis>{String(cellValue)}</Emphasis>;
  }

  switch (fieldType?.type) {
    case FieldTypeType.Array:
      return listRenderer(cellValue, fieldType.types ?? [], unit);
    case FieldTypeType.Timeframe:
    case FieldTypeType.Record:
      return <ComplexQueryRecordPlaceholder />;
    case FieldTypeType.Double:
    case FieldTypeType.Long:
    case FieldTypeType.Duration: {
      try {
        return formatDqlNumber(cellValue, fieldType.type, unit);
      } catch (exception) {
        // eslint-disable-next-line no-console
        console.error(exception);
        return '';
      }
    }
    case FieldTypeType.Timestamp:
      return timestampRenderer(cellValue);
    case FieldTypeType.Boolean:
    case FieldTypeType.String:
    default:
      return fallbackRenderer(
        truncateString(cellValue, options.largeTextTruncation),
      );
  }
}

/** Renders a cell content containing a list record. */
function listRenderer(
  value: ConversionCellValue,
  types: RangedFieldTypes[],
  unit?: Parameters<typeof formatDqlNumber>[2],
) {
  if (Array.isArray(value)) {
    const result: Array<string | number | boolean | ReactNode> = [];

    for (let i = 0; i < Math.min(value.length, MAX_PREVIEW_VALUES); i++) {
      const valueType = getTypesForRecordIndex(types, i)?.mappings['element'];
      if (
        valueType !== undefined &&
        (isNil(value[i]) ||
          [
            FieldTypeType.String,
            FieldTypeType.Double,
            FieldTypeType.Long,
            FieldTypeType.Boolean,
            FieldTypeType.Undefined,
          ].includes(valueType.type))
      ) {
        const isNumberType =
          valueType.type === FieldTypeType.Double ||
          valueType.type === FieldTypeType.Long;
        if (!isNumberType || !unit || typeof unit !== 'object') {
          result.push(cellRenderer(value[i], valueType));
          continue;
        }

        if (unit.input) {
          let convertedUnit = value[i];
          try {
            convertedUnit = convert(
              convertedUnit,
              unit.input as ConvertibleUnit,
              (unit.output || unit.input) as ConvertibleUnit,
            );
          } catch (error) {
            // Can't do anything about that
          }
          result.push(cellRenderer(convertedUnit, valueType));
        }
      } else {
        return (
          <span style={{ color: Colors.Text.Neutral.Subdued }}>
            {format(value.length)}
            <FormattedPlural
              value={value.length}
              other=" records"
              one=" record"
            />
          </span>
        );
      }
    }

    const valuesRemainingCount = value.length - MAX_PREVIEW_VALUES;
    if (valuesRemainingCount > 0) {
      result.push(
        <FormattedMessage
          key="more"
          id="+XBLTGLTVCPVRz9n"
          defaultMessage="{count, number} more"
          values={{ count: valuesRemainingCount }}
        />,
      );
    }

    let unitDisplayValue = '';
    if (typeof unit === 'string') {
      unitDisplayValue = unit;
    } else if (unit) {
      // Prefer displaying the `output` unit in parentheses at the end of the
      // array, and fall back to `input` unit.
      const displayUnit = unit.output || unit.input;
      if (displayUnit) {
        unitDisplayValue = formatUnit(displayUnit);
      }
    }

    unitDisplayValue = unitDisplayValue ? ` (${unitDisplayValue})` : '';

    return (
      <>
        <FormattedList
          style="long"
          type={valuesRemainingCount > 0 ? 'conjunction' : 'unit'}
          value={result}
        />{' '}
        {unitDisplayValue}
      </>
    );
  }

  return '';
}

/** Renders a cell content containing a timestamp record. */
function timestampRenderer(value: ConversionCellValue) {
  const dateValue = new Date(value);
  return !isNaN(dateValue.getTime()) ? <>{_formatDate(dateValue)}</> : '';
}
